// O formulário entrega todos os PDFs juntos, em um único item.
// Aqui separamos: um item por PDF, com o arquivo sempre no campo "data".
// Não dependemos do nome do campo (Curr_culo_0, Curr_culo_1...): pegamos
// todos os arquivos que chegarem, seja qual for o nome.
const results = [];

for (const item of $input.all()) {
  const binary = item.binary || {};
  for (const key of Object.keys(binary)) {
    const file = binary[key];
    results.push({
      json: { file: file.fileName || key },
      binary: { data: file },
    });
  }
}

return results;

// Junta o resultado de cada chamada ao /analyze em um único pedido
// para o /batch-report. Cada item vira {file, report} (deu certo) ou
// {file, error} (falhou). O nome do arquivo vem do nó "Separar PDFs",
// na mesma ordem das chamadas.
const names = $('Separar PDFs').all().map((item) => item.json.file);
const items = [];

$input.all().forEach((item, index) => {
  const data = item.json || {};
  const fallbackName = names[index] || 'arquivo_' + (index + 1);

  // Relatório do /analyze: tem summary e findings.
  if (data.summary && Array.isArray(data.findings)) {
    items.push({ file: data.file || fallbackName, report: data });
    return;
  }

  // Qualquer outra coisa é uma falha. Não sabemos o formato exato do erro
  // que o n8n entrega, então tentamos os lugares mais prováveis.
  let message = 'Falha ao chamar o /analyze.';
  if (data.error) {
    message = typeof data.error === 'string'
      ? data.error
      : (data.error.message || JSON.stringify(data.error));
  } else if (data.detail) {
    message = typeof data.detail === 'string'
      ? data.detail
      : JSON.stringify(data.detail);
  }
  items.push({ file: fallbackName, error: String(message).slice(0, 300) });
});

return [{ json: { items } }];

// Transforma a página HTML devolvida pelo /batch-report em um arquivo,
// para baixar pelo botão Download do n8n e abrir no navegador.
const data = $input.first().json;
const buffer = Buffer.from(data.html, 'utf-8');
const file = await this.helpers.prepareBinaryData(
  buffer,
  'relatorio_lote.html',
  'text/html'
);

return [{ json: { summary: data.summary }, binary: { data: file } }];
